{
  "instrument": "§ 356a BGB — BMJ page on the Widerrufsbutton",
  "jurisdiction": "DE",
  "summary": "Bieten Sie ab dem 19. Juni 2026 einen Widerrufsbutton an, mit dem Verbraucher in zwei Schritten widerrufen können. Die BMJ-Seite erläutert § 356a BGB, der die Richtlinie (EU) 2023/2673 für Online-Händler umsetzt.",
  "effective_dates": [
    "2026-06-19"
  ],
  "obligations": [
    {
      "text": "Bieten Sie Verbrauchern eine Widerrufsfunktion in zwei Schritten an.",
      "quote": "Ab dem 19. Juni 2026 müssen Online-Händler Verbraucherinnen und Verbrauchern eine Widerrufsfunktion („Widerrufsbutton\") anbieten, mit der ein Fernabsatzvertrag in zwei Schritten widerrufen werden kann."
    }
  ]
}
